// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List your API tokens (metadata only)
	// (GET /api-tokens)
	ListApiTokens(w http.ResponseWriter, r *http.Request)
	// Create an API token (the secret is returned only once)
	// (POST /api-tokens)
	CreateApiToken(w http.ResponseWriter, r *http.Request)
	// Revoke an API token
	// (DELETE /api-tokens/{id})
	DeleteApiToken(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List articles (paginated, newest first)
	// (GET /articles)
	ListArticles(w http.ResponseWriter, r *http.Request, params ListArticlesParams)
	// Get an article
	// (GET /articles/{id})
	GetArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Publish a draft article
	// (POST /articles/{id}/publish)
	PublishArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Rate an article (copywriter 👍/👎)
	// (POST /articles/{id}/rating)
	RateArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Authenticate and receive a JWT
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Clients with their derived funnel segment and tags, filtered/paginated — no date range, this is a snapshot of all-time activity, not a period aggregate
	// (GET /clients)
	ListClientSegments(w http.ResponseWriter, r *http.Request, params ListClientSegmentsParams)
	// The curated manual-tag vocabulary — AddClientTag only accepts a tag already listed here
	// (GET /clients/tag-defs)
	ListClientTagDefs(w http.ResponseWriter, r *http.Request)
	// Add a new entry to the tag vocabulary
	// (POST /clients/tag-defs)
	CreateClientTagDef(w http.ResponseWriter, r *http.Request)
	// Remove a tag definition — every client carrying it loses the tag too (idempotent, removing an already-gone label is not an error)
	// (DELETE /clients/tag-defs/{label})
	DeleteClientTagDef(w http.ResponseWriter, r *http.Request, label string)
	// Rename a tag definition and/or move it to another category — omitted fields are left as-is; a rename applies to every client carrying the old label in the same operation
	// (PATCH /clients/tag-defs/{label})
	UpdateClientTagDef(w http.ResponseWriter, r *http.Request, label string)
	// Delete a client record — refused (409) if it has any leads, consultations, or cases, so real business history can't be destroyed by accident
	// (DELETE /clients/{id})
	DeleteClient(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// One client's full card — leads, consultations, cases, manual notes, money actually collected
	// (GET /clients/{id})
	GetClientDetail(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Edit a client's own name/phone from the client card
	// (PATCH /clients/{id})
	UpdateClient(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Add a manual call/contact log entry to a client's card — free text staff types in after a call, there's no phone system integration
	// (POST /clients/{id}/notes)
	AddClientNote(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Pin a client's segment by hand, or pass null to clear the override and fall back to the calculated value
	// (PATCH /clients/{id}/segment)
	SetClientSegmentOverride(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Attach a tag to a client — tag must be one of GET /clients/tag-defs' labels; idempotent, adding a tag already present is not an error
	// (POST /clients/{id}/tags)
	AddClientTag(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Detach a staff-added tag from a client — idempotent, removing a tag that isn't present is not an error
	// (DELETE /clients/{id}/tags/{tag})
	RemoveClientTag(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, tag string)
	// Crawl the sites listed in a sheet and scrape their email addresses
	// (POST /emailscrape)
	ScrapeEmails(w http.ResponseWriter, r *http.Request)
	// Get the progress and state of a scrape job
	// (GET /emailscrape/jobs/{id})
	GetScrapeJob(w http.ResponseWriter, r *http.Request, id string)
	// Request cancellation of a running scrape job
	// (POST /emailscrape/jobs/{id}/cancel)
	CancelScrapeJob(w http.ResponseWriter, r *http.Request, id string)
	// Queue an article for generation
	// (POST /generate)
	GenerateArticle(w http.ResponseWriter, r *http.Request)
	// Queue a batch from the next N unused sheet topics
	// (POST /generate/batch)
	GenerateBatch(w http.ResponseWriter, r *http.Request)
	// Health check
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// Aggregate lead/consultation stats over a date range, for the admin dashboard
	// (GET /leads/stats)
	GetLeadStats(w http.ResponseWriter, r *http.Request, params GetLeadStatsParams)
	// Place a backlink to one of our WordPress sites in each suitable donor's latest post
	// (POST /linkbuilding/place-backlinks)
	PlaceBacklinks(w http.ResponseWriter, r *http.Request)
	// Per-donor results of a placement run
	// (GET /linkbuilding/placements)
	ListPlacements(w http.ResponseWriter, r *http.Request, params ListPlacementsParams)
	// Successful placements across all runs (paginated, newest first)
	// (GET /linkbuilding/placements/history)
	ListPlacementHistory(w http.ResponseWriter, r *http.Request, params ListPlacementHistoryParams)
	// Request cancellation of a running placement
	// (POST /linkbuilding/placements/{run_id}/cancel)
	CancelPlacement(w http.ResponseWriter, r *http.Request, runId string)
	// List users
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// List saved password/credential entries
	// (GET /vault-entries)
	ListVaultEntries(w http.ResponseWriter, r *http.Request)
	// Add a password/credential entry
	// (POST /vault-entries)
	CreateVaultEntry(w http.ResponseWriter, r *http.Request)
	// Delete a password/credential entry
	// (DELETE /vault-entries/{id})
	DeleteVaultEntry(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a password/credential entry
	// (PATCH /vault-entries/{id})
	UpdateVaultEntry(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List WordPress sites
	// (GET /wordpress-sites)
	ListWordpressSites(w http.ResponseWriter, r *http.Request)
	// Add a WordPress site
	// (POST /wordpress-sites)
	CreateWordpressSite(w http.ResponseWriter, r *http.Request)
	// Soft-delete a WordPress site
	// (DELETE /wordpress-sites/{id})
	DeleteWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get a WordPress site
	// (GET /wordpress-sites/{id})
	GetWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a WordPress site
	// (PATCH /wordpress-sites/{id})
	UpdateWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
}

